/* Sixth batch: real tools. Screen changers (need the "screen" permission), converters, calculators, text, time and notes. */
const { def } = require('./addon-library');
const J = JSON.stringify;
const ST = "var $=function(i){return document.getElementById(i)};function sv(k,v){try{aurora.storage.set(k,v).catch(function(){})}catch(e){}}";

/* ---------- 1. screen overlays ---------- */
function overlayApp(o) {
  const cfg = { mode: o.mode, color: o.color, opacity: o.opacity, size: o.size || 0, thickness: o.thickness || 2 };
  const hasSize = !!o.sizeLabel;
  const body = '<h3>' + o.name + '</h3><p class="muted">' + o.desc + '</p><p><button class="p" id="t">Turn on</button> <button id="off">Clear screen</button></p>' +
    '<p>Strength <input id="op" type="range" min="2" max="' + (o.mode === 'tint' ? 80 : 90) + '" value="' + Math.round(o.opacity * 100) + '"> <b id="ov"></b>%</p>' +
    (hasSize ? '<p>' + o.sizeLabel + ' <input id="sz" type="range" min="' + o.sizeMin + '" max="' + o.sizeMax + '" value="' + o.size + '"> <b id="sv"></b></p>' : '') +
    '<p>Colour <input id="co" type="color" value="' + o.color + '"></p><p class="muted" id="m">Emergency off: Ctrl+Alt+Shift+O</p>';
  const script = ST + ";var on=false,C=" + J(cfg) + ";\nfunction ap(){C.opacity=$('op').value/100;" + (hasSize ? "C.size=Number($('sz').value);$('sv').textContent=C.size;" : '') + "C.color=$('co').value;$('ov').textContent=$('op').value;sv('cfg',C);if(on)aurora.screen.overlay(C).catch(function(e){$('m').textContent=e.message})}\n" +
    "$('t').onclick=function(){on=!on;$('t').textContent=on?'Turn off':'Turn on';if(on)aurora.screen.overlay(C).catch(function(e){$('m').textContent=e.message;on=false;$('t').textContent='Turn on'});else aurora.screen.clear()};\n" +
    "$('off').onclick=function(){on=false;$('t').textContent='Turn on';aurora.screen.clear()};['op','co'" + (hasSize ? ",'sz'" : '') + "].forEach(function(k){$(k).oninput=ap});\n" +
    "aurora.storage.get('cfg').then(function(v){if(v&&v.mode===C.mode){$('op').value=Math.round(v.opacity*100);$('co').value=v.color;" + (hasSize ? "if(v.size)$('sz').value=v.size;" : '') + "}ap()}).catch(function(){ap()});";
  def('x6_' + o.key, 'a6-' + o.key, o.name, o.icon, o.desc, ['screen', 'storage'], body, script);
}
