/* ---------- 2. brightness and warmth ---------- */
def('x6_bright', 'a6-brightness', 'Brightness slider', '🔆', 'Change real screen brightness (laptops on Windows, any screen on Aurora OS).', ['screen'],
  '<h3>Brightness</h3><p><input id="r" type="range" min="10" max="100" value="100" style="width:80%"> <b id="v">100</b>%</p><p><button id="b30">30%</button> <button id="b60">60%</button> <button id="b100">100%</button></p><p class="muted" id="m"></p>',
  "var $=function(i){return document.getElementById(i)};function go(v){$('r').value=v;$('v').textContent=v;aurora.screen.setBrightness(Number(v)).then(function(){$('m').textContent=''}).catch(function(e){$('m').textContent=e.message})}\n$('r').oninput=function(){go($('r').value)};$('b30').onclick=function(){go(30)};$('b60').onclick=function(){go(60)};$('b100').onclick=function(){go(100)};aurora.screen.getBrightness().then(function(v){$('r').value=v;$('v').textContent=v}).catch(function(e){$('m').textContent=e.message});");
def('x6_warm', 'a6-warmth', 'Screen warmth (night light)', '🌙', 'Make the whole display warmer, like a real night light. Works on Aurora OS.', ['screen'],
  '<h3>Night light</h3><p>Warmth <input id="k" type="range" min="1500" max="6500" value="6500" style="width:60%"> <b id="v">6500</b>K</p><p><button id="n">Night (3400K)</button> <button id="c">Candle (2000K)</button> <button id="x">Normal</button></p><p class="muted" id="m">Lower number = warmer.</p>',
  "var $=function(i){return document.getElementById(i)};function go(k){$('k').value=k;$('v').textContent=k;aurora.screen.warmth(Number(k)).catch(function(e){$('m').textContent=e.message})}\n$('k').oninput=function(){go($('k').value)};$('n').onclick=function(){go(3400)};$('c').onclick=function(){go(2000)};$('x').onclick=function(){go(6500)};");
def('x6_sched', 'a6-night-schedule', 'Auto night mode', '⏰', 'Switches to a warm tint at a time you choose and back in the morning. Keep this add-on open.', ['screen', 'storage'],
  '<h3>Auto night mode</h3><p>Night starts <input id="a" type="time" value="20:00"> ends <input id="b" type="time" value="06:30"></p><p>Strength <input id="o" type="range" min="5" max="60" value="25"> <b id="ov">25</b>%</p><p>Status: <b id="s">checking</b></p>',
  ST + ";var on=false,cfg={a:'20:00',b:'06:30',o:25};function inNight(){var n=new Date(),m=n.getHours()*60+n.getMinutes(),p=function(t){var x=t.split(':');return Number(x[0])*60+Number(x[1])},a=p(cfg.a),b=p(cfg.b);return a>b?(m>=a||m<b):(m>=a&&m<b)}\nfunction tick(){cfg.a=$('a').value;cfg.b=$('b').value;cfg.o=Number($('o').value);$('ov').textContent=cfg.o;var want=inNight();if(want&&!on){on=true;aurora.screen.overlay({mode:'tint',color:'#ff8a00',opacity:cfg.o/100}).catch(function(e){$('s').textContent=e.message})}else if(!want&&on){on=false;aurora.screen.clear()}else if(want&&on){aurora.screen.overlay({mode:'tint',color:'#ff8a00',opacity:cfg.o/100}).catch(function(){})}$('s').textContent=want?'Night (filter on)':'Day (filter off)';sv('cfg',cfg)}\n['a','b','o'].forEach(function(k){$(k).onchange=tick});aurora.storage.get('cfg').then(function(v){if(v){cfg=v;$('a').value=v.a;$('b').value=v.b;$('o').value=v.o}tick()}).catch(tick);setInterval(tick,30000);");

