def('x6_eyebreak', 'a6-eye-break', 'Eye break (20-20-20)', '👁️', 'Every 20 minutes the screen dims for 20 seconds so you look away. Real protection for your eyes.', ['screen', 'notify', 'storage'],
  '<h3>20-20-20 eye break</h3><p class="muted">Every 20 minutes look at something 20 feet away for 20 seconds.</p><p>Next break in <b id="n">20:00</b></p><p>Every <input id="m" type="number" min="5" max="90" value="20" style="width:60px"> minutes <button class="p" id="g">Start</button></p>',
  ST + ";var run=false,left=1200,brk=0;function f(s){return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}\n$('g').onclick=function(){run=!run;$('g').textContent=run?'Stop':'Start';left=Number($('m').value)*60;brk=0;aurora.screen.clear();sv('m',$('m').value)};\nsetInterval(function(){if(!run)return;if(brk>0){brk--;$('n').textContent='Look away '+brk+'s';if(brk===0){aurora.screen.clear();left=Number($('m').value)*60}return}left--;$('n').textContent=f(Math.max(left,0));if(left<=0){brk=20;aurora.screen.overlay({mode:'tint',color:'#000000',opacity:0.8}).catch(function(){});aurora.notify('Look at something far away for 20 seconds').catch(function(){})}},1000);aurora.storage.get('m').then(function(v){if(v){$('m').value=v}}).catch(function(){});");
def('x6_pomodoro', 'a6-focus-dim', 'Focus sessions with screen dim', '🍅', 'A work timer. During breaks the screen turns warm so you really rest.', ['screen', 'notify'],
  '<h3>Focus sessions</h3><p><b id="p" style="font-size:34px">25:00</b></p><p id="s" class="muted">Ready</p><p>Work <input id="w" type="number" value="25" min="1" max="90" style="width:55px">min Break <input id="b" type="number" value="5" min="1" max="30" style="width:55px">min <button class="p" id="g">Start</button></p>',
  "var $=function(i){return document.getElementById(i)},work=true,left=1500,run=false;function f(s){return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}\n$('g').onclick=function(){run=!run;$('g').textContent=run?'Stop':'Start';if(!run)aurora.screen.clear();else{work=true;left=Number($('w').value)*60;$('s').textContent='Working'}};\nsetInterval(function(){if(!run)return;left--;$('p').textContent=f(Math.max(left,0));if(left<=0){work=!work;if(work){aurora.screen.clear();left=Number($('w').value)*60;$('s').textContent='Working';aurora.notify('Back to work').catch(function(){})}else{left=Number($('b').value)*60;$('s').textContent='Break time';aurora.screen.overlay({mode:'tint',color:'#ff8a00',opacity:0.45}).catch(function(){});aurora.notify('Break time. Stretch!').catch(function(){})}}},1000);");
