/* ---------- 4. unit converters ---------- */
function unitApp(key, name, icon, units, base) {
  const opts = units.map((u) => '<option value="' + u[1] + '">' + u[0] + '</option>').join('');
  const body = '<h3>' + name + '</h3><p><input id="v" type="number" value="1" style="width:130px"> <select id="a">' + opts + '</select> to <select id="b">' + opts + '</select></p><p style="font-size:22px"><b id="r">-</b></p><div id="all" class="muted"></div>';
  const script = "var $=function(i){return document.getElementById(i)},T=" + (base === 'temp') + ";\nfunction tc(v,f,t){var c=f==='C'?v:f==='F'?(v-32)*5/9:v-273.15;return t==='C'?c:t==='F'?c*9/5+32:c+273.15}\nfunction cv(v,a,b){return T?tc(v,a,b):v*Number(a)/Number(b)}\nfunction up(){var v=Number($('v').value),a=$('a').value,b=$('b').value,r=cv(v,a,b);$('r').textContent=(Math.round(r*1e6)/1e6)+' '+$('b').selectedOptions[0].text;var s='';[].forEach.call($('b').options,function(o){s+=o.text+': '+Math.round(cv(v,a,o.value)*1e5)/1e5+'  '});$('all').textContent=s}\n['v','a','b'].forEach(function(k){$(k).oninput=up;$(k).onchange=up});$('b').selectedIndex=1;up();";
  def('x6_' + key, 'a6-' + key, name, icon, 'Convert between ' + units.slice(0, 4).map((u) => u[0].toLowerCase()).join(', ') + ' and more.', [], body, script);
}
