unitApp('time', 'Time converter', '⏳', [['Seconds', 1], ['Minutes', 60], ['Hours', 3600], ['Days', 86400], ['Weeks', 604800], ['Years (365d)', 31536000]]);
unitApp('energy', 'Energy converter', '⚡', [['Joules', 1], ['Kilojoules', 1000], ['Calories (food)', 4184], ['Kilowatt-hours', 3600000], ['BTU', 1055.06]]);
