/* ---------- 5. text tools ---------- */
const TXT = (id, rows) => '<textarea id="i" rows="' + (rows || 6) + '" style="width:100%;box-sizing:border-box" placeholder="Type or paste text here"></textarea>' + (id || '');
def('x6_case', 'a6-case-changer', 'Case changer', '🔠', 'UPPER, lower, Title, camelCase, snake_case and kebab-case in one click.', ['clipboard'],
  '<h3>Case changer</h3>' + TXT('<p><button id="u">UPPER</button> <button id="l">lower</button> <button id="t">Title Case</button> <button id="c">camelCase</button> <button id="s">snake_case</button> <button id="k">kebab-case</button> <button class="p" id="cp">Copy</button></p>'),
  "var $=function(i){return document.getElementById(i)};function w(s){return s.trim().split(/[^A-Za-z0-9]+|(?<=[a-z])(?=[A-Z])/).filter(Boolean)}function set(f){$('i').value=f($('i').value)}\n$('u').onclick=function(){set(function(s){return s.toUpperCase()})};$('l').onclick=function(){set(function(s){return s.toLowerCase()})};$('t').onclick=function(){set(function(s){return s.toLowerCase().replace(/\\b\\w/g,function(c){return c.toUpperCase()})})};$('c').onclick=function(){set(function(s){return w(s).map(function(x,i){x=x.toLowerCase();return i?x[0].toUpperCase()+x.slice(1):x}).join('')})};$('s').onclick=function(){set(function(s){return w(s).join('_').toLowerCase()})};$('k').onclick=function(){set(function(s){return w(s).join('-').toLowerCase()})};$('cp').onclick=function(){aurora.copy($('i').value)};");
def('x6_count', 'a6-word-counter', 'Word counter', '🔤', 'Words, characters, sentences and reading time as you type.', [],
  '<h3>Word counter</h3>' + TXT('<p>Words <b id="w">0</b> · Characters <b id="c">0</b> · No spaces <b id="n">0</b> · Sentences <b id="s">0</b> · Reading time <b id="r">0</b> min</p>', 8),
  "var $=function(i){return document.getElementById(i)};$('i').oninput=function(){var t=$('i').value,w=(t.match(/\\S+/g)||[]).length;$('w').textContent=w;$('c').textContent=t.length;$('n').textContent=t.replace(/\\s/g,'').length;$('s').textContent=(t.match(/[.!?]+(\\s|$)/g)||[]).length;$('r').textContent=Math.max(w?1:0,Math.round(w/230))};");
def('x6_lorem', 'a6-lorem-ipsum', 'Placeholder text maker', '📃', 'Generate filler paragraphs for designs and mockups.', ['clipboard'],
  '<h3>Placeholder text</h3><p>Paragraphs <input id="n" type="number" min="1" max="12" value="3" style="width:60px"> <button class="p" id="g">Make</button> <button id="c">Copy</button></p><textarea id="o" rows="9" style="width:100%;box-sizing:border-box"></textarea>',
  "var $=function(i){return document.getElementById(i)},W='lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua enim ad minim veniam quis nostrud exercitation ullamco laboris nisi aliquip ex ea commodo consequat duis aute irure in reprehenderit voluptate velit esse cillum fugiat nulla pariatur'.split(' ');function p(){var n=8+Math.floor(Math.random()*8),s=[];for(var i=0;i<n;i++)s.push(W[Math.floor(Math.random()*W.length)]);var t=s.join(' ');return t[0].toUpperCase()+t.slice(1)+'.'}\n$('g').onclick=function(){var o=[];for(var i=0;i<Number($('n').value);i++){var x=[];for(var j=0;j<3+Math.floor(Math.random()*3);j++)x.push(p());o.push(x.join(' '))}$('o').value=o.join('\\n\\n')};$('c').onclick=function(){aurora.copy($('o').value)};$('g').onclick();");
