def('x6_roman', 'a6-roman', 'Roman numerals', '🏛️', 'Convert numbers to Roman numerals and back.', [],
  '<h3>Roman numerals</h3><p><input id="n" type="number" min="1" max="3999" value="2026" style="width:110px"> = <b id="r"></b></p><p><input id="t" placeholder="MMXXVI" style="width:110px"> = <b id="v"></b></p>',
  "var $=function(i){return document.getElementById(i)},P=[[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];function to(n){var s='';P.forEach(function(p){while(n>=p[0]){s+=p[1];n-=p[0]}});return s}function from(s){s=s.toUpperCase();var n=0,i=0;P.forEach(function(p){while(s.substr(i,p[1].length)===p[1]){n+=p[0];i+=p[1].length}});return i===s.length?n:'?'}\n$('n').oninput=function(){var n=Number($('n').value);$('r').textContent=n>0&&n<4000?to(n):'1-3999 only'};$('t').oninput=function(){$('v').textContent=$('t').value?from($('t').value):''};$('n').oninput();");

