def('x6_random', 'a6-random-numbers', 'Random number picker', '🎲', 'Pick random numbers in a range, with or without repeats.', [],
  '<h3>Random numbers</h3><p>From <input id="a" type="number" value="1" style="width:70px"> to <input id="b" type="number" value="100" style="width:70px"> how many <input id="n" type="number" value="5" min="1" max="100" style="width:60px"> <label><input id="u" type="checkbox"> unique</label> <button class="p" id="g">Pick</button></p><p style="font-size:22px"><b id="o">-</b></p>',
  "var $=function(i){return document.getElementById(i)};$('g').onclick=function(){var a=Number($('a').value),b=Number($('b').value),n=Number($('n').value),o=[];if(b<a){var t=a;a=b;b=t}if($('u').checked&&n>b-a+1)n=b-a+1;while(o.length<n){var x=a+Math.floor(Math.random()*(b-a+1));if(!$('u').checked||o.indexOf(x)<0)o.push(x)}$('o').textContent=o.join(', ')};");
