calc('bmi', 'BMI calculator', '🏃', 'Body mass index from weight and height. A rough guide only, not medical advice.', [['w', 'Weight (kg)', 70], ['h', 'Height (cm)', 175]], "(function(){var b=n('w')/Math.pow(n('h')/100,2),c=b<18.5?'under the usual range':b<25?'in the usual range':b<30?'above the usual range':'well above the usual range';return ['BMI: '+f(b,1),'That is '+c+' for adults.']})()");
calc('loan', 'Loan calculator', '🏦', 'Monthly payment and total interest for a loan.', [['p', 'Amount', 100000], ['r', 'Yearly interest %', 5], ['y', 'Years', 10]], "(function(){var m=n('r')/1200,k=n('y')*12,pay=m?n('p')*m/(1-Math.pow(1+m,-k)):n('p')/k;return ['Monthly payment: '+f(pay),'Total paid: '+f(pay*k),'Total interest: '+f(pay*k-n('p'))]})()");
calc('discount', 'Discount calculator', '🏷️', 'Final price after a discount, and how much you save.', [['p', 'Price', 200], ['d', 'Discount %', 25]], "['You save: '+f(n('p')*n('d')/100),'You pay: '+f(n('p')*(1-n('d')/100))]");
calc('fuel', 'Trip fuel cost', '⛽', 'Fuel and cost for a trip.', [['d', 'Distance (km)', 300], ['c', 'Litres per 100 km', 8], ['p', 'Price per litre', 2.3]], "['Fuel needed: '+f(n('d')*n('c')/100)+' L','Trip cost: '+f(n('d')*n('c')/100*n('p'))]");
calc('split', 'Bill splitter', '🧮', 'Split a bill evenly with optional service charge.', [['b', 'Bill', 240], ['s', 'People', 4], ['c', 'Service %', 10]], "['Each pays: '+f(n('b')*(1+n('c')/100)/Math.max(1,n('s'))),'Total: '+f(n('b')*(1+n('c')/100))]");
calc('saving', 'Savings goal', '🐷', 'How long to reach a savings goal with monthly saving.', [['g', 'Goal', 10000], ['m', 'Save per month', 500], ['s', 'Already saved', 0]], "(function(){var k=Math.ceil(Math.max(0,n('g')-n('s'))/Math.max(1,n('m')));return ['Months needed: '+k,'About '+f(k/12,1)+' years']})()");
calc('ratio', 'Aspect ratio helper', '🖼️', 'Work out a new height from a width, keeping the same shape.', [['w', 'Original width', 1920], ['h', 'Original height', 1080], ['nw', 'New width', 1280]], "['New height: '+f(n('nw')*n('h')/n('w'),0),'Ratio: '+f(n('w')/n('h'),3)+':1']");
def('x6_date', 'a6-date-diff', 'Date difference', '🗓️', 'Days, weeks and months between two dates, and what day a date falls on.', [],
  '<h3>Date difference</h3><p><input id="a" type="date"> to <input id="b" type="date"></p><div id="o" style="font-size:18px;line-height:1.6"></div>',
  "var $=function(i){return document.getElementById(i)},d=new Date().toISOString().slice(0,10);$('a').value=d;$('b').value=d;function up(){var a=new Date($('a').value),b=new Date($('b').value),n=Math.round((b-a)/864e5);$('o').textContent=Math.abs(n)+' days ('+(Math.abs(n)/7).toFixed(1)+' weeks, about '+(Math.abs(n)/30.44).toFixed(1)+' months). Day of the first date: '+a.toLocaleDateString(undefined,{weekday:'long'})}$('a').oninput=up;$('b').oninput=up;up();");
def('x6_age', 'a6-age', 'Age calculator', '🎂', 'Exact age in years, months and days, and days to the next birthday.', [],
  '<h3>Age calculator</h3><p>Born <input id="b" type="date" value="2000-01-01"></p><div id="o" style="font-size:18px;line-height:1.6"></div>',
  "var $=function(i){return document.getElementById(i)};function up(){var b=new Date($('b').value),n=new Date(),y=n.getFullYear()-b.getFullYear(),m=n.getMonth()-b.getMonth(),d=n.getDate()-b.getDate();if(d<0){m--;d+=new Date(n.getFullYear(),n.getMonth(),0).getDate()}if(m<0){y--;m+=12}var nx=new Date(n.getFullYear(),b.getMonth(),b.getDate());if(nx<n)nx.setFullYear(n.getFullYear()+1);$('o').textContent=y+' years, '+m+' months, '+d+' days. Next birthday in '+Math.ceil((nx-n)/864e5)+' days.'}$('b').oninput=up;up();");

