def('x6_world', 'a6-world-clock', 'World clock', '🌍', 'See the time in cities around the world. Remembers your list.', ['storage'],
  '<h3>World clock</h3><div id="o"></div><p><select id="z"></select> <button class="p" id="a">Add</button></p>',
  ST + ";var Z=['Asia/Riyadh','Asia/Dubai','Europe/London','Europe/Paris','America/New_York','America/Los_Angeles','Asia/Tokyo','Asia/Shanghai','Asia/Kolkata','Australia/Sydney','Africa/Cairo','America/Sao_Paulo','Europe/Istanbul','Asia/Karachi'],L=['Asia/Riyadh','Europe/London','America/New_York'];Z.forEach(function(z){var o=document.createElement('option');o.textContent=z;$('z').appendChild(o)});\nfunction show(){$('o').textContent='';L.forEach(function(z,i){var p=document.createElement('p');p.style.fontSize='18px';var t=new Date().toLocaleTimeString([],{timeZone:z,hour:'2-digit',minute:'2-digit',second:'2-digit'});p.textContent=z.split('/').pop().replace('_',' ')+': '+t+' ';var b=document.createElement('button');b.textContent='x';b.onclick=function(){L.splice(i,1);sv('L',L);show()};p.appendChild(b);$('o').appendChild(p)})}\n$('a').onclick=function(){if(L.indexOf($('z').value)<0){L.push($('z').value);sv('L',L)}show()};aurora.storage.get('L').then(function(v){if(Array.isArray(v))L=v;show()}).catch(show);setInterval(show,1000);");
def('x6_stopwatch', 'a6-stopwatch', 'Stopwatch with laps', '⏱️', 'A precise stopwatch with lap times.', [],
  '<h3>Stopwatch</h3><p><b id="t" style="font-size:38px;font-variant-numeric:tabular-nums">00:00.00</b></p><p><button class="p" id="s">Start</button> <button id="l">Lap</button> <button id="r">Reset</button></p><ol id="o"></ol>',
  "var $=function(i){return document.getElementById(i)},run=false,t0=0,acc=0,iv;function f(ms){var s=ms/1000;return String(Math.floor(s/60)).padStart(2,'0')+':'+(s%60).toFixed(2).padStart(5,'0')}function cur(){return acc+(run?Date.now()-t0:0)}\n$('s').onclick=function(){if(run){acc+=Date.now()-t0;run=false;clearInterval(iv)}else{t0=Date.now();run=true;iv=setInterval(function(){$('t').textContent=f(cur())},30)}$('s').textContent=run?'Stop':'Start'};$('l').onclick=function(){var li=document.createElement('li');li.textContent=f(cur());$('o').insertBefore(li,$('o').firstChild)};$('r').onclick=function(){run=false;clearInterval(iv);acc=0;$('t').textContent='00:00.00';$('o').textContent='';$('s').textContent='Start'};");
def('x6_countdown', 'a6-countdown-timer', 'Countdown timer', '⏲️', 'Set a timer and get a desktop notification when it ends.', ['notify'],
  '<h3>Timer</h3><p><b id="t" style="font-size:38px">05:00</b></p><p><input id="m" type="number" min="1" max="600" value="5" style="width:70px"> min <button class="p" id="g">Start</button> <button id="b1">1</button> <button id="b5">5</button> <button id="b10">10</button> <button id="b30">30</button></p>',
  "var $=function(i){return document.getElementById(i)},left=0,iv;function f(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}\n$('g').onclick=function(){clearInterval(iv);left=Number($('m').value)*60;$('t').textContent=f(left);iv=setInterval(function(){left--;$('t').textContent=f(Math.max(left,0));if(left<=0){clearInterval(iv);aurora.notify('Time is up!').catch(function(){})}},1000)};[1,5,10,30].forEach(function(x){$('b'+x).onclick=function(){$('m').value=x;$('g').onclick()}});");
def('x6_water', 'a6-water-reminder', 'Water reminder', '💧', 'A reminder to drink water at the interval you choose, with a daily glass count.', ['notify', 'storage'],
  '<h3>Water reminder</h3><p>Remind me every <input id="m" type="number" min="10" max="240" value="45" style="width:60px"> minutes <button class="p" id="g">Start</button></p><p>Glasses today: <b id="n">0</b> <button id="d">I drank one</button></p>',
  ST + ";var run=false,iv,key=new Date().toDateString(),n=0;$('g').onclick=function(){run=!run;$('g').textContent=run?'Stop':'Start';clearInterval(iv);if(run)iv=setInterval(function(){aurora.notify('Time for a glass of water').catch(function(){})},Number($('m').value)*60000)};$('d').onclick=function(){n++;$('n').textContent=n;sv('w',{d:key,n:n})};aurora.storage.get('w').then(function(v){if(v&&v.d===key){n=v.n;$('n').textContent=n}}).catch(function(){});");
def('x6_stand', 'a6-stand-reminder', 'Stretch reminder', '🧘', 'A nudge to stand up and stretch during long work sessions.', ['notify'],
  '<h3>Stretch reminder</h3><p>Every <input id="m" type="number" min="15" max="180" value="50" style="width:60px"> minutes <button class="p" id="g">Start</button></p><p class="muted">Keep this add-on open while you work.</p>',
  "var $=function(i){return document.getElementById(i)},iv,run=false,T=['Stand up and stretch your back','Roll your shoulders','Walk for two minutes','Look out of the window','Shake out your hands'];$('g').onclick=function(){run=!run;$('g').textContent=run?'Stop':'Start';clearInterval(iv);if(run)iv=setInterval(function(){aurora.notify(T[Math.floor(Math.random()*T.length)]).catch(function(){})},Number($('m').value)*60000)};");
def('x6_meeting', 'a6-meeting-cost', 'Meeting cost meter', '💼', 'See how much a meeting is costing while it runs.', [],
  '<h3>Meeting cost</h3><p>People <input id="p" type="number" value="6" style="width:60px"> Average hourly cost <input id="r" type="number" value="40" style="width:70px"> <button class="p" id="g">Start</button></p><p style="font-size:34px"><b id="c">0.00</b></p><p><b id="t">00:00</b></p>',
  "var $=function(i){return document.getElementById(i)},run=false,t0=0,iv;$('g').onclick=function(){run=!run;$('g').textContent=run?'Stop':'Start';clearInterval(iv);if(run){t0=Date.now();iv=setInterval(function(){var s=(Date.now()-t0)/1000;$('c').textContent=(s/3600*Number($('p').value)*Number($('r').value)).toFixed(2);$('t').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0')},250)}};");

/* ---------- 9. notes and productivity ---------- */
def('x6_sticky', 'a6-sticky-note', 'Sticky note', '🗒️', 'A note that saves itself as you type.', ['storage'],
  '<h3>Sticky note</h3><textarea id="i" rows="12" style="width:100%;box-sizing:border-box;background:#fff3a3;color:#222;border-radius:10px;padding:10px"></textarea><p class="muted" id="m">Saved automatically</p>',
  ST + ";var tm;aurora.storage.get('t').then(function(v){if(typeof v==='string')$('i').value=v}).catch(function(){});$('i').oninput=function(){clearTimeout(tm);tm=setTimeout(function(){sv('t',$('i').value.slice(0,15000));$('m').textContent='Saved'},400)};");
function listApp(key, name, icon, desc, ph, checks) {
  def('x6_' + key, 'a6-' + key, name, icon, desc, ['storage'],
    '<h3>' + name + '</h3><p><input id="i" placeholder="' + ph + '" style="width:70%"> <button class="p" id="a">Add</button></p><div id="o"></div><p><button id="cl">Clear finished</button></p>',
    ST + ";var L=[];function save(){sv('L',L)}function show(){$('o').textContent='';L.forEach(function(it,i){var p=document.createElement('p'),c=document.createElement('input');c.type='checkbox';c.checked=it.d;c.onchange=function(){it.d=c.checked;save();show()};var s=document.createElement('span');s.textContent=' '+it.t+' ';if(it.d)s.style.textDecoration='line-through';var x=document.createElement('button');x.textContent='x';x.onclick=function(){L.splice(i,1);save();show()};p.append(c,s,x);$('o').appendChild(p)})}\n$('a').onclick=function(){var t=$('i').value.trim();if(!t||L.length>=100)return;L.push({t:t.slice(0,120),d:false});$('i').value='';save();show()};$('i').onkeydown=function(e){if(e.key==='Enter')$('a').onclick()};$('cl').onclick=function(){L=L.filter(function(x){return !x.d});save();show()};aurora.storage.get('L').then(function(v){if(Array.isArray(v))L=v;show()}).catch(show);");
}
listApp('todo', 'To-do list', '✅', 'Simple tasks you tick off. Remembers everything.', 'What needs doing?');
listApp('shop', 'Shopping list', '🛒', 'A shopping list that remembers what you still need.', 'Add an item');
listApp('packing', 'Packing list', '🧳', 'Never forget what to pack for a trip.', 'Add something to pack');
listApp('watch', 'Watch later list', '🎞️', 'Movies and shows you want to see.', 'Title');
listApp('read', 'Reading list', '📕', 'Books and articles to read next.', 'Title or link');
def('x6_habit', 'a6-habit-tracker', 'Habit tracker', '📈', 'Track daily habits and see your streaks.', ['storage'],
  '<h3>Habits</h3><p><input id="i" placeholder="New habit" style="width:60%"> <button class="p" id="a">Add</button></p><div id="o"></div>',
  ST + ";var H=[],today=new Date().toISOString().slice(0,10);function streak(h){var n=0,d=new Date();while(h.days.indexOf(d.toISOString().slice(0,10))>=0){n++;d.setDate(d.getDate()-1)}return n}function save(){sv('H',H)}\nfunction show(){$('o').textContent='';H.forEach(function(h,i){var p=document.createElement('p'),b=document.createElement('button'),done=h.days.indexOf(today)>=0;b.textContent=done?'Done today':'Mark done';b.onclick=function(){var k=h.days.indexOf(today);if(k>=0)h.days.splice(k,1);else h.days.push(today);h.days=h.days.slice(-400);save();show()};var s=document.createElement('span');s.textContent=' '+h.n+'  streak: '+streak(h)+' days ';var x=document.createElement('button');x.textContent='x';x.onclick=function(){H.splice(i,1);save();show()};p.append(b,s,x);$('o').appendChild(p)})}\n$('a').onclick=function(){var t=$('i').value.trim();if(!t||H.length>=30)return;H.push({n:t.slice(0,40),days:[]});$('i').value='';save();show()};aurora.storage.get('H').then(function(v){if(Array.isArray(v))H=v;show()}).catch(show);");
def('x6_snip', 'a6-snippets', 'Text snippets', '📎', 'Save phrases you type often and copy them in one click.', ['storage', 'clipboard'],
  '<h3>Snippets</h3><p><input id="i" placeholder="Text to save" style="width:70%"> <button class="p" id="a">Save</button></p><div id="o"></div>',
  ST + ";var L=[];function save(){sv('L',L)}function show(){$('o').textContent='';L.forEach(function(t,i){var p=document.createElement('p'),b=document.createElement('button');b.textContent='Copy';b.onclick=function(){aurora.copy(t).then(function(){aurora.toast('Copied')})};var s=document.createElement('span');s.textContent=' '+t.slice(0,60)+' ';var x=document.createElement('button');x.textContent='x';x.onclick=function(){L.splice(i,1);save();show()};p.append(b,s,x);$('o').appendChild(p)})}\n$('a').onclick=function(){var t=$('i').value.trim();if(!t||L.length>=50)return;L.push(t.slice(0,500));$('i').value='';save();show()};aurora.storage.get('L').then(function(v){if(Array.isArray(v))L=v;show()}).catch(show);");
def('x6_journal', 'a6-journal', 'Daily journal', '📔', 'One page per day. Write a few lines and they are kept.', ['storage'],
  '<h3>Journal</h3><p><input id="d" type="date"></p><textarea id="i" rows="10" style="width:100%;box-sizing:border-box"></textarea><p class="muted" id="m"></p>',
  ST + ";var tm;$('d').value=new Date().toISOString().slice(0,10);function load(){aurora.storage.get('j'+$('d').value).then(function(v){$('i').value=typeof v==='string'?v:''}).catch(function(){})}$('d').onchange=load;$('i').oninput=function(){clearTimeout(tm);tm=setTimeout(function(){sv('j'+$('d').value,$('i').value.slice(0,15000));$('m').textContent='Saved'},400)};load();");
def('x6_mood', 'a6-mood-log', 'Mood log', '🙂', 'Tap how you feel each day and see the last two weeks.', ['storage'],
  '<h3>Mood log</h3><p style="font-size:28px"><span id="b"></span></p><p class="muted">Last 14 days</p><p style="font-size:22px" id="h"></p>',
  ST + ";var E=['😞','😕','😐','🙂','😄'],M={},day=new Date().toISOString().slice(0,10);E.forEach(function(e,i){var b=document.createElement('button');b.textContent=e;b.onclick=function(){M[day]=i;sv('M',M);show()};$('b').appendChild(b)});function show(){var s='';for(var i=13;i>=0;i--){var d=new Date();d.setDate(d.getDate()-i);var k=d.toISOString().slice(0,10);s+=(M[k]!==undefined?E[M[k]]:'·')+' '}$('h').textContent=s}aurora.storage.get('M').then(function(v){if(v&&typeof v==='object')M=v;show()}).catch(show);");
def('x6_expense', 'a6-expense-log', 'Expense log', '🧾', 'Write down what you spend and see the total.', ['storage'],
  '<h3>Expenses</h3><p><input id="n" placeholder="What" style="width:40%"> <input id="a" type="number" step="any" placeholder="Amount" style="width:90px"> <button class="p" id="g">Add</button></p><p>Total: <b id="t">0</b></p><div id="o"></div>',
  ST + ";var L=[];function save(){sv('L',L)}function show(){$('o').textContent='';var t=0;L.forEach(function(e,i){t+=e.a;var p=document.createElement('p');p.textContent=e.n+': '+e.a+' ';var x=document.createElement('button');x.textContent='x';x.onclick=function(){L.splice(i,1);save();show()};p.appendChild(x);$('o').appendChild(p)});$('t').textContent=Math.round(t*100)/100}\n$('g').onclick=function(){var a=Number($('a').value);if(!$('n').value||!isFinite(a)||L.length>=150)return;L.push({n:$('n').value.slice(0,40),a:a});$('n').value='';$('a').value='';save();show()};aurora.storage.get('L').then(function(v){if(Array.isArray(v))L=v;show()}).catch(show);");

/* ---------- 10. colour tools ---------- */
def('x6_contrast', 'a6-contrast-check', 'Contrast checker', '♿', 'Check if text and background colours are easy enough to read (WCAG).', [],
  '<h3>Contrast checker</h3><p>Text <input id="a" type="color" value="#ffffff"> Background <input id="b" type="color" value="#1d4ed8"></p><div id="p" style="padding:18px;border-radius:12px;font-size:20px">Sample text looks like this</div><p>Ratio <b id="r"></b> · <b id="v"></b></p>',
  "var $=function(i){return document.getElementById(i)};function L(h){var n=parseInt(h.slice(1),16),c=[n>>16&255,n>>8&255,n&255].map(function(x){x/=255;return x<=0.03928?x/12.92:Math.pow((x+0.055)/1.055,2.4)});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]}function up(){var a=L($('a').value),b=L($('b').value),r=(Math.max(a,b)+0.05)/(Math.min(a,b)+0.05);$('p').style.color=$('a').value;$('p').style.background=$('b').value;$('r').textContent=r.toFixed(2)+':1';$('v').textContent=r>=7?'AAA (excellent)':r>=4.5?'AA (good)':r>=3?'Large text only':'Poor'}$('a').oninput=up;$('b').oninput=up;up();");
def('x6_hexrgb', 'a6-colour-codes', 'Colour code converter', '🖌️', 'Convert between HEX, RGB and HSL.', ['clipboard'],
  '<h3>Colour codes</h3><p><input id="c" type="color" value="#4cc2ff"></p><p>HEX <code id="h"></code></p><p>RGB <code id="r"></code></p><p>HSL <code id="l"></code></p><p><button id="x">Copy HEX</button></p>',
  "var $=function(i){return document.getElementById(i)};function up(){var h=$('c').value,n=parseInt(h.slice(1),16),r=n>>16&255,g=n>>8&255,b=n&255,R=r/255,G=g/255,B=b/255,mx=Math.max(R,G,B),mn=Math.min(R,G,B),l=(mx+mn)/2,s=0,H=0;if(mx!==mn){var d=mx-mn;s=l>0.5?d/(2-mx-mn):d/(mx+mn);H=mx===R?(G-B)/d+(G<B?6:0):mx===G?(B-R)/d+2:(R-G)/d+4;H*=60}$('h').textContent=h.toUpperCase();$('r').textContent='rgb('+r+', '+g+', '+b+')';$('l').textContent='hsl('+Math.round(H)+', '+Math.round(s*100)+'%, '+Math.round(l*100)+'%)'}$('c').oninput=up;$('x').onclick=function(){aurora.copy($('h').textContent)};up();");
def('x6_shades', 'a6-shade-maker', 'Shade maker', '🎚️', 'Make lighter and darker shades of one colour.', ['clipboard'],
  '<h3>Shades</h3><p><input id="c" type="color" value="#7c3aed"></p><div id="o" style="display:flex;height:80px;border-radius:12px;overflow:hidden"></div><p class="muted" id="m">Click a shade to copy</p>',
  "var $=function(i){return document.getElementById(i)};function mix(h,t,a){var n=parseInt(h.slice(1),16),c=[n>>16&255,n>>8&255,n&255].map(function(x){return Math.round(x+(t-x)*a)});return '#'+c.map(function(x){return x.toString(16).padStart(2,'0')}).join('')}function up(){var o=$('o');o.textContent='';[0.8,0.6,0.4,0.2,0,-0.2,-0.4,-0.6,-0.8].forEach(function(a){var c=a>=0?mix($('c').value,255,a):mix($('c').value,0,-a),d=document.createElement('div');d.style.cssText='flex:1;background:'+c+';cursor:pointer';d.title=c;d.onclick=function(){aurora.copy(c).then(function(){$('m').textContent='Copied '+c})};o.appendChild(d)})}$('c').oninput=up;up();");

/* ---------- 11. Ramadan and daily-life tools ---------- */
def('x6_tasbih', 'a6-tasbih', 'Tasbih counter', '📿', 'A digital tasbih. Tap to count, pick a target, and it remembers your count.', ['storage'],
  '<h3>Tasbih</h3><p style="text-align:center"><button id="t" style="width:200px;height:200px;border-radius:50%;font-size:64px" class="p">0</button></p><p style="text-align:center">Target <select id="g"><option>33</option><option>99</option><option>100</option><option>0</option></select> (0 = no target) <button id="r">Reset</button></p><p class="muted" style="text-align:center" id="m"></p>',
  ST + ";var n=0;function up(){var g=Number($('g').value);$('t').textContent=n;$('m').textContent=g?(n>=g?'Target reached':'Remaining: '+(g-n)):'';sv('n',{n:n,g:$('g').value})}\n$('t').onclick=function(){n++;up()};$('r').onclick=function(){n=0;up()};$('g').onchange=up;aurora.storage.get('n').then(function(v){if(v){n=v.n||0;$('g').value=v.g||'33'}up()}).catch(up);");
def('x6_zakat', 'a6-zakat', 'Zakat calculator', '🕌', 'Estimate zakat (2.5%) on savings, gold and silver. Enter your own values; check details with a scholar.', [],
  '<h3>Zakat calculator</h3><p>Cash and savings <input id="a" type="number" value="0" style="width:120px"></p><p>Gold (grams) <input id="g" type="number" value="0" style="width:90px"> price per gram <input id="gp" type="number" value="0" style="width:90px"></p><p>Silver (grams) <input id="s" type="number" value="0" style="width:90px"> price per gram <input id="sp" type="number" value="0" style="width:90px"></p><p>Business goods and money owed to you <input id="b" type="number" value="0" style="width:120px"></p><p>Debts due now <input id="d" type="number" value="0" style="width:120px"></p><div id="o" style="font-size:18px;line-height:1.7"></div><p class="muted">Nisab is based on 85 g of gold or 595 g of silver (silver is the lower, more cautious amount). This is an estimate only.</p>',
  "var $=function(i){return document.getElementById(i)},n=function(i){return Number($(i).value)||0};function up(){var tot=n('a')+n('g')*n('gp')+n('s')*n('sp')+n('b')-n('d'),nis=Math.min(85*n('gp')||Infinity,595*n('sp')||Infinity);$('o').textContent='';function l(t){var d=document.createElement('div');d.textContent=t;$('o').appendChild(d)}l('Zakatable wealth: '+tot.toLocaleString());if(isFinite(nis)){l('Nisab: '+Math.round(nis).toLocaleString());l(tot>=nis?'Zakat due (2.5%): '+(tot*0.025).toLocaleString(undefined,{maximumFractionDigits:2}):'Below the nisab, no zakat due')}else l('Enter a gold or silver price to see the nisab')}['a','g','gp','s','sp','b','d'].forEach(function(k){$(k).oninput=up});up();");
def('x6_hijri', 'a6-hijri-converter', 'Hijri date converter', '🌙', 'Convert between Gregorian and Hijri dates. Calculated dates can differ by a day from moon sighting.', [],
  '<h3>Hijri converter</h3><p>Gregorian date <input id="g" type="date"></p><p><b id="h" style="font-size:20px"></b></p><hr><p>Hijri <input id="hy" type="number" value="1448" style="width:80px"> / <input id="hm" type="number" min="1" max="12" value="1" style="width:55px"> / <input id="hd" type="number" min="1" max="30" value="1" style="width:55px"></p><p><b id="gg" style="font-size:20px"></b></p>',
  "var $=function(i){return document.getElementById(i)},M=['Muharram','Safar','Rabi al-awwal','Rabi al-thani','Jumada al-awwal','Jumada al-thani','Rajab','Shaban','Ramadan','Shawwal','Dhu al-Qidah','Dhu al-Hijjah'];function T(a,b){return a<0?Math.ceil(a/b):Math.floor(a/b)}\nfunction toH(y,m,d){var jd=T(1461*(y+4800+T(m-14,12)),4)+T(367*(m-2-12*T(m-14,12)),12)-T(3*T(y+4900+T(m-14,12),100),4)+d-32075,l=jd-1948440+10632,n=T(l-1,10631);l=l-10631*n+354;var j=T(10985-l,5316)*T(50*l,17719)+T(l,5670)*T(43*l,15238);l=l-T(30-j,15)*T(17719*j,50)-T(j,16)*T(15238*j,43)+29;var mm=T(24*l,709),dd=l-T(709*mm,24);return[30*n+j-30,mm,dd]}\nfunction toG(hy,hm,hd){var jd=T(11*hy+3,30)+354*hy+30*hm-T(hm-1,2)+hd+1948440-385,l=jd+68569,n=T(4*l,146097);l=l-T(146097*n+3,4);var i=T(4000*(l+1),1461001);l=l-T(1461*i,4)+31;var j=T(80*l,2447),d=l-T(2447*j,80);l=T(j,11);return[100*(n-49)+i+l,j+2-12*l,d]}\nfunction a(){var v=$('g').value;if(!v)return;var p=v.split('-').map(Number),h=toH(p[0],p[1],p[2]);$('h').textContent=h[2]+' '+M[h[1]-1]+' '+h[0]+' AH'}function b(){var g=toG(Number($('hy').value),Number($('hm').value),Number($('hd').value));$('gg').textContent=g[0]+'-'+String(g[1]).padStart(2,'0')+'-'+String(g[2]).padStart(2,'0')}\n$('g').value=new Date().toISOString().slice(0,10);$('g').oninput=a;['hy','hm','hd'].forEach(function(k){$(k).oninput=b});a();b();");
def('x6_ramadan', 'a6-ramadan-tracker', 'Ramadan tracker', '🌟', 'Tick off each day you fasted and each part (juz) of the Quran you finished. Remembers everything.', ['storage'],
  '<h3>Ramadan tracker</h3><p>Fasting days: <b id="fc">0</b>/30</p><div id="days" style="display:grid;grid-template-columns:repeat(10,1fr);gap:6px"></div><p>Quran parts finished: <b id="qc">0</b>/30</p><div id="juz" style="display:grid;grid-template-columns:repeat(10,1fr);gap:6px"></div>',
  ST + ";var D=[],Q=[];for(var i=0;i<30;i++){D.push(0);Q.push(0)}function build(el,arr,key,cnt){el.textContent='';arr.forEach(function(v,i){var b=document.createElement('button');b.textContent=i+1;b.style.padding='6px 0';if(v)b.className='p';b.onclick=function(){arr[i]=arr[i]?0:1;sv(key,arr);show()};el.appendChild(b)});$(cnt).textContent=arr.reduce(function(a,c){return a+c},0)}\nfunction show(){build($('days'),D,'D','fc');build($('juz'),Q,'Q','qc')}aurora.storage.get('D').then(function(v){if(Array.isArray(v)&&v.length===30)D=v;return aurora.storage.get('Q')}).then(function(v){if(Array.isArray(v)&&v.length===30)Q=v;show()}).catch(show);");
def('x6_qibla', 'a6-qibla', 'Qibla direction', '🧭', 'Find the compass direction to the Kaaba from your latitude and longitude. Check with a compass or your phone.', [],
  '<h3>Qibla direction</h3><p>Latitude <input id="la" type="number" step="any" value="24.7136" style="width:110px"> Longitude <input id="lo" type="number" step="any" value="46.6753" style="width:110px"></p><p style="font-size:22px"><b id="o"></b></p><div style="width:160px;height:160px;border-radius:50%;border:2px solid var(--line);margin:auto;position:relative"><div id="n" style="position:absolute;left:50%;top:50%;width:4px;height:70px;background:var(--accent);transform-origin:50% 0;border-radius:2px"></div></div><p class="muted">Defaults to Riyadh. Direction is measured clockwise from true north.</p>',
  "var $=function(i){return document.getElementById(i)};function up(){var f=Number($('la').value)*Math.PI/180,l=Number($('lo').value)*Math.PI/180,kf=21.4225*Math.PI/180,kl=39.8262*Math.PI/180,dl=kl-l,y=Math.sin(dl),x=Math.cos(f)*Math.tan(kf)-Math.sin(f)*Math.cos(dl),b=(Math.atan2(y,x)*180/Math.PI+360)%360;$('o').textContent=b.toFixed(1)+'° from north';$('n').style.transform='rotate('+(b+180)+'deg)'}$('la').oninput=up;$('lo').oninput=up;up();");
